CREATE OR REPLACE FUNCTION public.live_automation_ai_admission(p_actor uuid, p_kind text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.live_automation_actors; t timestamptz:=clock_timestamp(); total_minute integer; proactive_minute integer; proactive_hour integer; begin
 perform public.live_automation_assert_ai(p_actor);
 select * into a from public.live_automation_actors where id=p_actor;
 if p_kind<>'reply' and exists(select 1 from public.live_automation_campaigns where id=a.campaign_id and auto_chat_after>t) then raise exception 'ROOM_CHAT_REST';end if;
 if p_kind<>'reply' and exists(select 1 from public.live_chat_messages m join public.live_automation_campaigns c on c.broadcast_id=m.broadcast_id where c.id=a.campaign_id and m.automation_actor_id is null and m.badge is distinct from 'bot' and m.hidden_at is null and m.created_at>t-(case public.live_automation_chat_pace() when 'high' then interval '25 seconds' when 'normal' then interval '45 seconds' else interval '90 seconds' end)) then raise exception 'HUMAN_CONVERSATION_ACTIVE';end if;
 if p_kind not in('reply','chat','question') then raise exception 'INVALID_AI_KIND'; end if;
 select count(*) filter(where m.created_at>t-interval '1 minute'),
   count(*) filter(where m.created_at>t-interval '1 minute' and x.kind<>'reply'),
   count(*) filter(where x.kind<>'reply')
 into total_minute,proactive_minute,proactive_hour
 from public.live_chat_messages m join public.live_automation_actions x on x.id=m.automation_action_id
 where x.campaign_id=a.campaign_id and m.created_at>t-interval '1 hour';
 if total_minute>=2 then raise exception 'CHAT_MINUTE_LIMIT'; end if;
 if p_kind<>'reply' and (proactive_minute>=1 or proactive_hour>=6 or a.proactive_quiet_until>t) then raise exception 'CHAT_QUIET_WINDOW'; end if;
end $function$

CREATE OR REPLACE FUNCTION public.live_automation_room_chat_rest()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare a public.live_automation_actions; delay integer;begin
 if new.automation_action_id is null or new.badge='bot' or new.hidden_at is not null then return new;end if;
 select * into a from public.live_automation_actions where id=new.automation_action_id;
 if a.kind not in('chat','question','reply') then return new;end if;
 delay:=case public.live_automation_chat_pace()
   when 'high' then case when a.kind='reply' then 10+floor(random()*16)::int else 15+floor(random()*26)::int end
   when 'normal' then case when a.kind='reply' then 30+floor(random()*31)::int else 45+floor(random()*76)::int end
   else case when a.kind='reply' then 180+floor(random()*181)::int when random()<.2 then 900+floor(random()*901)::int else 240+floor(random()*481)::int end end;
 update public.live_automation_campaigns set auto_chat_after=greatest(auto_chat_after,clock_timestamp()+make_interval(secs=>delay)) where id=a.campaign_id;
 return new;
end $function$

CREATE OR REPLACE FUNCTION public.live_automation_sparse_chat_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
declare action public.live_automation_actions; begin
 if new.automation_cart_action_id is not null and new.kakao_id='bot:ruru' and new.badge='bot' and public.live_automation_cart_notice_valid(new.automation_cart_action_id,new.automation_actor_id,new.automation_session_id,new.broadcast_id,new.body,new.bot_ref) then return new; end if;
 if new.automation_payment_action_id is not null and new.kakao_id='bot:ruru' and new.badge='bot' and public.live_automation_payment_notice_valid(new.automation_payment_action_id,new.automation_actor_id,new.automation_session_id,new.broadcast_id,new.body,new.bot_ref) then return new; end if;
 if new.automation_actor_id is null or new.automation_manual_request_id is not null then return new; end if;
 if new.automation_action_id is null and new.kakao_id='bot:ruru' and exists(
   select 1 from public.live_automation_actions a where a.id::text=nullif(current_setting('ruru.live_automation_notice',true),'')
   and a.status='succeeded' and a.actor_id=new.automation_actor_id and a.session_id=new.automation_session_id and new.bot_ref='o:'||a.order_group_id)
 then return new; end if;
 select * into action from public.live_automation_actions where id=new.automation_action_id;
 if action.id is null or action.actor_id<>new.automation_actor_id or action.status<>'claimed' then raise exception 'INVALID_CHAT_ACTION'; end if;
 perform public.live_automation_ai_admission(new.automation_actor_id,action.kind);
 if action.kind<>'reply' then
   update public.live_automation_actors set proactive_quiet_until=clock_timestamp()+make_interval(secs=>300+floor(random()*601)::int) where id=new.automation_actor_id;
 end if;
 return new;
end $function$
